/**
 * Get appropriate icon and color for a connector based on its name
 * @param connectorName - Name of the connector
 * @param size - Size of the icon (default: 24)
 * @returns React node containing the icon
 */
export const getConnectorIcon = (
  connectorName: string,
  size: number = 24,
): React.ReactNode => {
  const name = connectorName.toLowerCase().trim();

  // Check if we have a specific mapping for this connector
  const connectorKey = Object.keys(connectorIconMap).find(
    (key) => key === name || name.includes(key) || key.includes(name),
  );

  if (connectorKey) {
    const { Icon, color, width, height } = connectorIconMap[connectorKey];
    const sizeClass =
      size === 24 ? "w-6 h-6" : size === 32 ? "w-8 h-8" : "w-5 h-5";

    // Check if Icon is a string (image path) or a React component
    if (typeof Icon === "string") {
      // Use custom width/height if provided, otherwise use sizeClass
      // Parse width/height by removing 'px' suffix if present
      const parseSize = (
        sizeStr: string | undefined,
        defaultSize: number,
      ): number => {
        if (!sizeStr) return defaultSize;
        return Number(sizeStr.replace(/px$/, ""));
      };
      const imageWidth = parseSize(
        width,
        size === 24 ? 24 : size === 32 ? 32 : 20,
      );
      const imageHeight = parseSize(
        height,
        size === 24 ? 24 : size === 32 ? 32 : 20,
      );
      return (
        <Image
          src={Icon}
          alt={connectorName}
          width={imageWidth}
          height={imageHeight}
          className={sizeClass}
          style={{ objectFit: "contain" }}
        />
      );
    }

    return <Icon className={`${sizeClass} ${color}`} />;
  }

  // Fallback logic for connectors not in the map
  let Icon = Plug;
  let color = "text-cyan-500";

  // Version Control & Development
  if (name.includes("git")) {
    Icon = Code2;
    color = "text-orange-600";
  }
  // Communication
  else if (name.includes("chat") || name.includes("message")) {
    Icon = MessageSquare;
    color = "text-blue-500";
  }
  // Cloud
  else if (name.includes("cloud")) {
    Icon = Cloud;
    color = "text-blue-500";
  }
  // Database
  else if (name.includes("database") || name.includes("db")) {
    Icon = Database;
    color = "text-blue-700";
  }
  // Financial
  else if (
    name.includes("payment") ||
    name.includes("billing") ||
    name.includes("invoice")
  ) {
    Icon = CreditCard;
    color = "text-green-600";
  }
  // File & Storage
  else if (name.includes("storage") || name.includes("file")) {
    Icon = FolderOpen;
    color = "text-blue-500";
  }
  // Email
  else if (name.includes("mail") || name.includes("email")) {
    Icon = Mail;
    color = "text-red-500";
  }
  // Security
  else if (name.includes("security") || name.includes("auth")) {
    Icon = Lock;
    color = "text-red-600";
  }
  // Monitoring
  else if (
    name.includes("monitor") ||
    name.includes("analytics") ||
    name.includes("report")
  ) {
    Icon = BarChart3;
    color = "text-purple-600";
  }

  const sizeClass =
    size === 24 ? "w-6 h-6" : size === 32 ? "w-8 h-8" : "w-5 h-5";
  return <Icon className={`${sizeClass} ${color}`} />;
};

/**
 * Get connector label
 */
export const getConnectorLabel = (connectorName: string): string => {
  const name = connectorName.toLowerCase().trim();
  const connectorKey = Object.keys(connectorIconMap).find(
    (key) => key === name || name.includes(key) || key.includes(name),
  );

  return connectorKey ? connectorIconMap[connectorKey].label : connectorName;
};
